if ((sa_input.sun == NULL) || (sa_input.boresight == NULL) ||
    (!adcs_is_finite_vec3(sa_input.sun)) || (!adcs_is_finite_vec3(sa_input.boresight)) ||
    (!isfinite(a)) || (!isfinite(b)) || (!(b >= -1.0 && b < a && a <= 1.0))) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    sa_output.correction_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

if (adcs_vec3_normalize(sa_input.sun, ADCS_EPS_NORM, &sun_n) != ADCS_OK ||
    adcs_vec3_normalize(sa_input.boresight, ADCS_EPS_NORM, &boresight_n) != ADCS_OK) {
    sa_state.mode = SA_FAULT;
    sa_output.mode = SA_FAULT;
    sa_output.cosine = 0.0;
    sa_output.angle_rad = 0.0;
    sa_output.correction_axis = (adcs_vec3_t){0.0, 0.0, 0.0};
    return;
}

cosine = adcs_vec3_dot(&sun_n, &boresight_n);
if (cosine > 1.0) cosine = 1.0;
if (cosine < -1.0) cosine = -1.0;
angle = acos(cosine);
cross = adcs_vec3_cross(&sun_n, &boresight_n);
cross_norm = adcs_vec3_norm(&cross);
if (cross_norm > ADCS_EPS_COLLINEAR) {
    axis = adcs_vec3_scale(&cross, 1.0 / cross_norm);
} else {
    axis = (adcs_vec3_t){0.0, 0.0, 0.0};
}

if (sa_input.enable == 0) {
    next_mode = SA_OFF;
    axis = (adcs_vec3_t){0.0, 0.0, 0.0};
} else if (sa_state.mode == SA_ACTIVE) {
    if (cosine > b) {
        next_mode = SA_ACTIVE;
    } else {
        next_mode = SA_OFF;
    }
} else {
    if (cosine < a) {
        next_mode = SA_OFF;
    } else {
        next_mode = SA_ACTIVE;
    }
}

sa_state.mode = next_mode;
sa_output.mode = next_mode;
sa_output.cosine = cosine;
sa_output.angle_rad = angle;
sa_output.correction_axis = axis;
